D['00236']=dict(version='3',context='bcc',title='Vismodegib for advanced basal cell skin cancer',url='https://healthservice.hse.ie/documents/6725/236_v3_Vismodegib.pdf',cycle=28,kind='skin_vismodegib_continuous',therapy='Targeted therapy',service='targeted',scope='NCCP 00236: symptomatic metastatic basal cell carcinoma, or locally advanced basal cell carcinoma unsuitable for surgery or radiotherapy.',purpose='Vismodegib is used to help control advanced basal cell skin cancer when the source-specific criteria are met. Discuss whether the aim is shrinkage, symptom relief, longer disease control or another agreed goal, and how surgery or radiotherapy has been considered.',schedule='Take vismodegib once every day at the same time, continuously while the team considers it beneficial and tolerable. A 28-day calendar organises the four-week review; it is not a planned seven-day break or a fixed number of courses.',short='Vismodegib daily; four-week safety review. No routine treatment-free week.',admin='Swallow the prescribed capsule whole with about 200 mL of water, with or without food, at the same time each day. Do not open, crush or chew it. Keep it in its labelled pack, away from children, and return unused capsules to the pharmacy.',missed='If a dose is missed, skip it and take the next dose at the usual time. Do not double up. If you vomit after taking it, ask the oncology team or pharmacist before taking more; do not assume that the dose needs replacing.',baseline='Full blood count, kidney and liver tests; medicine review and pregnancy-prevention programme assessment for women and men. If pregnancy is possible, a supervised pregnancy test is needed within seven days before starting.',during='Full blood count, kidney and liver tests every four weeks. Review cramps, strength, taste, eating, weight, hair/skin changes and treatment tolerance. Pregnancy testing is monthly when applicable, even if periods stop.',after='Agree continuing clinical/skin review, any response imaging and support for ongoing effects. The pregnancy-prevention, donation and breastfeeding restrictions continue after the last dose for their specified periods.',pregnancy='Vismodegib can cause severe harm to an unborn baby. Women who could become pregnant need the formal pregnancy-prevention programme, including two recommended contraceptive methods unless the agreed alternative is continuous abstinence, during treatment and for 24 months after stopping. Pregnancy tests are supervised before treatment and monthly, even with absent periods. Men must use a condom during sex with a woman during treatment and for two months afterwards, including after a vasectomy. Report a suspected patient or partner pregnancy immediately. Do not breastfeed or donate blood during treatment or for 24 months afterwards; do not donate semen during treatment or for two months afterwards. Ask the team to explain and document the full programme; this summary does not replace its materials.',urgent='Call urgently for blistering or peeling skin, mouth sores with rash or fever, severe muscle pain or weakness, or dark urine. Seek immediate advice about suspected pregnancy or exposure. Report taste change, reduced eating and weight loss early so support can start.',agents=[agent('vismodegib','Vismodegib','Erivedge','Oral targeted capsule','Blocks the Hedgehog growth pathway','Vismodegib blocks a protein called Smoothened in the Hedgehog signalling pathway. This pathway can drive basal cell cancer growth. Blocking it can also affect normal hair follicles, taste and muscle function, which helps explain hair loss, altered taste and cramps. This treatment is different from a cream applied to a skin lesion.',['Daily capsule','Hedgehog signal blocked','Cancer growth may slow'],'Keep four-week blood tests and the pregnancy-prevention programme. Report cramps, loss of strength, reduced intake, weight loss and severe skin symptoms.',['Muscle spasms and muscle/joint pain','Altered or lost taste and poor appetite','Weight loss and fatigue','Hair loss','Nausea, diarrhoea or constipation','Rare severe skin reactions','Severe harm to pregnancy; prolonged prevention requirements'],['Muscle cramps','Taste / appetite','Weight','Skin / hair'])],anatomy=[['brain','Energy / daily activity','Vismodegib','Tiredness can affect daily tasks. Tell the team if it worsens or comes with dizziness, reduced eating or other new symptoms.',50,5],['hair','Hair / scalp','Vismodegib','Hair may thin or fall out. Ask about scalp care, sun protection and practical support; the timing of recovery varies.',45,3],['mouth','Taste / eating','Vismodegib','Taste may change or disappear, making food less appealing. Report reduced intake early and ask for dietitian help.',50,12.5],['skin','Skin','Vismodegib','A rash with blistering, peeling, mouth sores or fever needs urgent assessment. Keep scheduled skin reviews and report new lesions.',22,37],['muscles','Muscles / strength','Vismodegib','Cramps and muscle pain are common concerns. Severe pain, weakness or dark urine needs urgent advice; do not add supplements or medicines yourself.',64,65],['bowel','Stomach / bowels','Vismodegib','Nausea, diarrhoea or constipation may occur. Call if symptoms persist, you cannot drink or urine becomes reduced.',50,44],['nutrition','Appetite / weight','Vismodegib','Taste changes and poor appetite can cause weight loss. Keep a practical eating plan and tell the team about loose clothes or falling weight.',44,32],['pelvis','Pregnancy / fertility','Vismodegib','A strict pregnancy-prevention programme applies to women and men, with restrictions continuing after treatment. Report possible exposure immediately.',50,57]],warnings=['The formal pregnancy-prevention programme is essential; restrictions continue after stopping.','A four-week review calendar does not create a routine drug holiday.','Routine CPK testing is not specified by the cited NCCP schedule; muscle symptoms need individual assessment.'])
D['00415']=dict(version='4',context='melanoma',title='Dabrafenib and trametinib for BRAF-mutated melanoma',url='https://healthservice.hse.ie/documents/6732/415_v4_Trametinib_and_DabrafenibTherapy.pdf',cycle=28,kind='skin_dabrafenib_trametinib_continuous',therapy='Targeted therapy',service='targeted',scope='NCCP 00415: BRAF V600-mutated unresectable/metastatic melanoma, or adjuvant treatment after complete resection of stage III BRAF V600-mutated melanoma. The team records which setting applies.',purpose='Dabrafenib and trametinib block two points in a growth pathway used by BRAF V600-mutated melanoma. In advanced disease the aim is disease control; after complete removal of eligible stage III melanoma, adjuvant treatment aims to reduce the chance of recurrence. These settings have different endpoints and duration.',schedule='Take dabrafenib twice daily, around 12 hours apart, and trametinib once daily. Both are taken every day unless the team instructs a hold. Advanced melanoma continues while beneficial and tolerable; adjuvant treatment after complete resection of eligible stage III melanoma is planned for 12 months unless stopped earlier. A 28-day calendar is a review period, not a treatment-free week.',short='Dabrafenib twice daily + trametinib daily. Advanced: ongoing review. Adjuvant: planned 12 months.',admin='Swallow the prescribed capsules/tablet whole with water. Take each dose at least one hour before food or at least two hours after food. Take the once-daily trametinib dose at the same time each day, alongside either the morning or evening dabrafenib dose according to your written plan. Keep the prescribed storage instructions.',missed='The missed-dose windows differ: take missed dabrafenib only when more than six hours remain before the next dose; take missed trametinib only when more than 12 hours remain. Otherwise skip it. Do not double up. Do not take an extra trametinib dose after vomiting; contact the team or pharmacist about any vomited or uncertain dose.',baseline='Confirm the BRAF V600 tumour result and advanced versus adjuvant setting. Full blood count, kidney/liver tests, ECG and echocardiogram, skin examination and eye assessment when indicated.',during='Blood count, kidney/liver tests monthly. ECG and heart ultrasound at four weeks, then every 12 weeks and after dose modification in the NCCP schedule. Skin assessment every 60 days; head/neck examination every three months and chest CT every six months are specified surveillance checks. Disease-response imaging follows the individual plan.',after='Continue skin surveillance for six months after stopping as specified by the regimen, and arrange the ongoing melanoma follow-up plan. Review symptoms, heart/eye concerns and contraception instructions after treatment.',pregnancy='Discuss fertility preservation and pregnancy precautions before starting. These medicines can harm a pregnancy. Ask the pharmacist for the exact contraceptive methods and after-treatment duration for both drugs; dabrafenib can reduce the effectiveness of hormonal contraception. Do not breastfeed during treatment. Report a possible pregnancy promptly.',urgent='Fever is a particular concern. At 38°C or above, withhold both medicines and contact the oncology team promptly under the written fever plan; recurrent episodes may require action at the first symptoms. Infection and dehydration also need assessment. Restart only when the team tells you. Urgent help is also needed for vision change, severe rash, chest pain, breathlessness, bleeding or severe muscle symptoms.',agents=[agent('dabrafenib','Dabrafenib','Tafinlar','Oral BRAF inhibitor','Blocks altered BRAF signalling','A BRAF V600 change can keep the cell-growth pathway switched on. Dabrafenib blocks the altered BRAF protein. It is paired with a MEK inhibitor to act on the same pathway at another point. The BRAF result comes from tumour testing; it does not automatically mean a hereditary condition.',['BRAF V600 result','BRAF blocked','Growth signal reduced'],'Fever needs the written hold/contact plan. Check other medicines and contraception because interactions can matter.',['Fever and chills, dehydration','Skin rash and new skin tumours','Headache, fatigue and joint pain','Eye inflammation','Bleeding and liver changes','Harm to pregnancy and drug interactions'],['Fever / chills','Skin','Fatigue']),agent('trametinib','Trametinib','Mekinist','Oral MEK inhibitor','Blocks downstream MEK signalling','MEK carries growth signals further along the pathway below BRAF. Trametinib blocks MEK alongside dabrafenib. Normal heart, eye, lung and other tissues can also be affected, which is why scheduled tests and prompt symptom reporting matter.',['MEK signal blocked','Works with dabrafenib','Heart / eye monitoring'],'Attend cardiac tests. New eye symptoms, cough, breathlessness, swelling or severe diarrhoea need prompt review.',['Reduced heart pumping function','Retinal and other eye problems','Lung inflammation','Diarrhoea, swelling and rash','Bleeding, liver changes and muscle injury','Harm to pregnancy'],['Eyes','Breathing','Swelling','Bowels'])],anatomy=[['brain','Fever / chills','Both medicines','At 38°C or above, hold both medicines and contact the team under your fever plan. Infection and dehydration must also be considered.',50,5],['eyes','Eyes / vision','Dabrafenib / trametinib','Report blurred vision, eye pain, redness, light sensitivity or a change in sight promptly; some eye problems need urgent specialist treatment.',50,9],['heart','Heart / circulation','Trametinib / combination','Keep ECG and heart ultrasound checks. New breathlessness, swollen ankles, palpitations or chest pain needs prompt assessment.',48,25],['skin','Skin / new lesions','Both medicines','Rash and skin sensitivity may occur; new changing spots need review. Blistering, peeling or mouth sores with a rash needs urgent help.',22,37],['liver','Liver','Both medicines','Liver changes may first appear in blood tests. Report yellow eyes or skin, dark urine, unusual itching or upper-abdominal pain.',44,34],['kidneys','Kidneys / fluids','Both medicines / fever','Fever, vomiting or diarrhoea can cause dehydration and kidney problems. Call for reduced urine, dizziness or inability to keep fluids down.',57,39],['muscles','Muscles / joints','Both medicines','Aches can occur. Severe muscle pain or weakness, especially with dark urine, needs urgent advice and possible blood tests.',64,65],['bowel','Stomach / bowels','Both medicines','Tell the team about persistent diarrhoea, vomiting or pain. Severe abdominal pain, blood or black stools needs urgent assessment.',50,44]],warnings=['Advanced and adjuvant treatment are distinct; do not apply a 12-month endpoint to all patients.','Fever holds both drugs; other toxicities may have component-specific rules. The treating team decides restart and dose changes.','The historical PDF contains adjuvant00415b while the reviewed catalogue excerpt lists00415a; current source reconciliation must resolve/record this difference.'])
D['00563']=dict(version='3',context='melanoma',title='Encorafenib and binimetinib for advanced BRAF-mutated melanoma',url='https://healthservice.hse.ie/documents/6744/563_V3_Encorafenib-and-Binimetinib_Therapy.pdf',cycle=28,kind='skin_encorafenib_binimetinib_continuous',therapy='Targeted therapy',service='targeted',scope='NCCP 00563: adults with advanced unresectable or metastatic melanoma with a BRAF V600 mutation.',purpose='Encorafenib and binimetinib block two points in the BRAF-MEK growth pathway to help control eligible advanced melanoma. The team reviews response, symptoms and side effects to decide whether the treatment continues.',schedule='Take encorafenib once daily and binimetinib twice daily, around 12 hours apart, continuously unless the team tells you to hold them. Treatment continues while beneficial and tolerable. A 28-day review calendar does not mean a routine break or a fixed total number of cycles.',short='Encorafenib daily + binimetinib twice daily, continuously; reviewed regularly.',admin='Swallow the prescribed capsules/tablets whole with water. They may be taken with or without food. Keep doses at consistent times and follow the prescription for each medicine. Avoid grapefruit and grapefruit juice with encorafenib, and have all medicines and supplements checked for interactions.',missed='For a missed encorafenib dose, take it only if more than 12 hours remain before the next dose. For binimetinib, do not take a missed dose if fewer than six hours remain before the next; ask the pharmacist if timing is uncertain. Do not double doses. If either medicine is vomited, do not take an extra dose; take the next scheduled dose unless the team advises otherwise.',baseline='Confirm BRAF V600 and treatment setting. Full blood count, kidney/liver tests, creatine kinase (CK) and creatinine, blood pressure, ECG, a heart-pumping assessment by echo or MUGA, and skin examination.',during='Blood count, kidney/liver tests monthly. CK and creatinine monthly for the first six months, then as indicated. ECG at four weeks, then every 12 weeks and after dose changes; heart-pumping assessment every three months. Skin assessment every 60 days, head/neck examination every three months and chest CT every six months. Response scans follow the individual plan.',after='Continue skin surveillance for six months after stopping as specified by the regimen. Agree continuing symptom/organ checks, the next melanoma assessment and medicine-specific pregnancy precautions.',pregnancy='Discuss fertility and pregnancy precautions before starting. These medicines can harm a pregnancy. The pharmacist should document reliable contraception, possible medicine interactions and how long precautions continue after the last dose of each medicine. Do not breastfeed during treatment and seek prompt advice about any possible pregnancy.',urgent='Contact the team promptly for new visual symptoms, chest pain, breathlessness, palpitations, faintness, severe muscle pain or weakness, dark urine, bleeding, severe rash, persistent diarrhoea or severe abdominal pain. Do not continue one medicine at an unchanged dose if the other has been held without a specific team instruction.',agents=[agent('encorafenib','Encorafenib','Braftovi','Oral BRAF inhibitor','Blocks altered BRAF signalling','Encorafenib blocks the BRAF V600 growth signal in eligible melanoma cells. Binimetinib acts further down the same pathway. They have different dose schedules and different safety decisions, so the prescription for one must not be assumed to apply to the other.',['BRAF V600 confirmed','BRAF signal blocked','Partner MEK medicine'],'A change to binimetinib can change the encorafenib plan. Have interactions checked and avoid grapefruit.',['Skin reactions and new skin tumours','Nausea, vomiting, fatigue and joint pain','Bleeding and eye inflammation','Heart-rhythm and liver changes','Harm to pregnancy and interactions'],['Skin','Nausea','Fatigue']),agent('binimetinib','Binimetinib','Mektovi','Oral MEK inhibitor','Blocks downstream MEK signalling','Binimetinib inhibits MEK in the cell-growth pathway. It can also affect normal muscle, heart and retinal tissues. CK blood tests, heart checks and prompt reporting of eye or muscle changes help the team identify problems before they become more serious.',['MEK inhibited','Cancer-growth signal reduced','Muscle / heart / eye checks'],'Report vision change or muscle pain/weakness promptly; keep CK, kidney and heart checks even when you feel well.',['Reduced heart pumping function','Retinal/eye changes','Raised CK and muscle injury','Liver changes, diarrhoea and rash','Lung inflammation, clots and bleeding','Harm to pregnancy'],['Eyes','Muscles','Breathing','Bowels'])],anatomy=[['brain','Energy / fever','Both medicines','Fatigue and headache can occur. Fever, marked weakness, dizziness or new neurological symptoms needs advice; do not assume it is a harmless drug effect.',50,5],['eyes','Eyes / vision','Both medicines','Blurred vision, spots, altered colour vision or eye pain needs prompt assessment. Retinal problems may occur with binimetinib.',50,9],['heart','Heart / circulation','Both medicines','Keep ECG and heart-pumping checks. Report palpitations, fainting, swollen ankles or new breathlessness; severe chest pain is an emergency.',48,25],['skin','Skin / new lesions','Both medicines','Report new growths or changes in existing spots and attend skin checks. Severe rash, blistering or peeling needs urgent help.',22,37],['liver','Liver','Both medicines','Liver changes may have no early symptoms, so attend monthly tests. Report yellow skin or eyes, dark urine or upper-abdominal pain.',44,34],['kidneys','Kidneys / fluids','Binimetinib / combination','Kidney tests accompany CK monitoring. Reduced urine, dehydration or dark urine with muscle symptoms needs urgent advice.',57,39],['muscles','Muscles / strength','Binimetinib','CK can rise before or with muscle injury. Report muscle pain, weakness or dark urine, and keep the planned blood tests.',64,65],['bowel','Stomach / bowels','Both medicines','Nausea and diarrhoea may occur. Persistent vomiting, inability to drink, severe abdominal pain, black stools or bleeding needs assessment.',50,44]],warnings=['Temporary holds may need coordinated changes to both medicines; no patient-led dose adjustment.','The regimen is advanced melanoma; it is not an adjuvant treatment template.','No trial outcome percentage is assigned without confirming the exact population, comparison and follow-up.'])
D['00431']=dict(version='11',context='melanoma',title='Nivolumab and ipilimumab for advanced melanoma',url='https://healthservice.hse.ie/documents/6734/431_Nivolumab_1mg_Ipilimumab_3mg.pdf',cycle=21,kind='skin_nivo1_ipi3_induction_maintenance',therapy='Immunotherapy',service='immunotherapy',scope='NCCP 00431a: advanced unresectable or metastatic melanoma in adults. This patient guide is the melanoma context, not the separate liver-cancer indication.',purpose='Nivolumab and ipilimumab help immune cells recognise and attack melanoma. The combination phase is followed by nivolumab alone when appropriate. The aim in this setting is to control advanced disease; benefit and toxicity are reviewed for the individual.',schedule='The combination phase gives nivolumab followed by ipilimumab by IV infusion every three weeks for up to four doses. If appropriate, nivolumab alone then continues on the team-selected two-weekly or four-weekly schedule, by the prescribed IV or subcutaneous route. After the last combination dose, the first two-weekly maintenance dose starts three weeks later; the first four-weekly maintenance dose starts six weeks later in this melanoma schedule. Treatment continues until progression or unacceptable toxicity, subject to review.',short='Up to 4 combination visits, 3 weeks apart; then nivolumab alone every 2 or 4 weeks as prescribed.',admin='At each combination visit, nivolumab is given before ipilimumab, as separate IV infusions. The source schedule gives each over 30 minutes; allow extra time for assessment, preparation and observation. Maintenance may be IV or subcutaneous nivolumab with its own dose and appointment interval. The route and interval are recorded in your plan; they are not interchangeable on your own.',missed='If an appointment is missed or treatment is held, contact the unit for a new plan. Do not count a missed visit as a dose received. A move to maintenance does not erase previous immune toxicity or a permanent-stop decision.',baseline='Full blood count, kidney and liver tests, glucose and thyroid tests; BRAF tumour testing and review of autoimmune conditions, transplantation, prior immune reactions and current medicines.',during='Full blood count, kidney/liver tests, glucose and thyroid tests each treatment cycle. Cortisol and other tests are added when clinically indicated. Every visit also reviews bowel, breathing, skin, endocrine, neurological and other symptoms; a normal blood test does not exclude immune toxicity.',after='Continue to report possible immune effects for at least five months after the last dose, as specified by NCCP, and for longer whenever your team advises. Keep any steroid taper, hormone-replacement plan and relevant follow-up tests. Response imaging follows your individual plan.',pregnancy='Discuss fertility and pregnancy precautions before starting. Immunotherapy may harm a pregnancy. Use the contraception plan and after-treatment duration specified for the medicines you receive; ask about breastfeeding restrictions. Tell the team promptly about possible pregnancy. Do not stop necessary hormone replacement or prescribed steroids without advice.',urgent=IMMUNE,agents=[agent('nivolumab','Nivolumab','Opdivo','PD-1 checkpoint immunotherapy','Releases a PD-1 immune brake','Nivolumab blocks PD-1, a signal that can reduce T-cell activity. This can help immune cells act against melanoma, but it can also allow inflammation in healthy organs. It is not conventional chemotherapy and side effects can occur even after doses have stopped.',['PD-1 blocked','Immune activity increases','Healthy organs can inflame'],'Carry your immunotherapy alert card and report new symptoms early, including after treatment ends.',['Immune inflammation of bowel, lungs, liver or kidneys','Thyroid, pituitary, adrenal and glucose problems','Skin reactions and rare severe skin injury','Rare heart, muscle, neurological and eye inflammation','Infusion or injection reactions','Some immune effects need long-term treatment'],['Bowels','Breathing','Skin','Fatigue']),agent('ipilimumab','Ipilimumab','Yervoy','CTLA-4 checkpoint immunotherapy','Releases a second immune brake','Ipilimumab blocks CTLA-4, another checkpoint involved in controlling T cells. Combining it with nivolumab increases immune activity and can increase immune-related toxicity. The four-dose combination phase has a different treatment plan from nivolumab maintenance.',['CTLA-4 blocked','Combined immune activation','Four-dose induction phase'],'New diarrhoea, abdominal pain, severe headache or unusual weakness needs early contact. Do not wait for the next infusion.',['Immune colitis and severe diarrhoea','Liver, endocrine and skin inflammation','Rare neurological, eye, heart or muscle inflammation','Infusion reactions','Immune effects during or after treatment'],['Diarrhoea','Abdominal pain','Headache','Weakness'])],anatomy=[],warnings=['This is nivolumab1/ipilimumab3, not the lower-ipilimumab combination.','Four induction doses do not mean the whole treatment course is four doses.','Prior immune toxicity and permanent-stop decisions remain relevant when maintenance starts.','No routine percentage dose reductions: the team may hold or stop immunotherapy and treat the adverse effect.'])
D['00812']=dict(version='3a',context='cscc',title='Cemiplimab for advanced cutaneous squamous cell cancer',url='https://healthservice.hse.ie/documents/6426/812_V3a_Cemiplimab.pdf',cycle=21,kind='skin_cemiplimab_cscc_21_day',therapy='Immunotherapy',service='immunotherapy',scope='NCCP 00812b: metastatic or locally advanced cutaneous squamous cell carcinoma when curative surgery or curative radiotherapy is not appropriate. This guide covers skin SCC, not the separate cervical-cancer indication.',purpose='Cemiplimab helps immune cells act against advanced cutaneous squamous cell cancer when curative surgery or radiotherapy is not suitable. The team reviews cancer control, symptoms, side effects and your priorities to decide whether to continue.',schedule='Cemiplimab is given by IV infusion on Day 1 every 21 days. The usual source dose is 350 mg over 30 minutes; the prescription and visit checks confirm your treatment. There is no fixed cycle total in this regimen: treatment continues while the team considers it beneficial and tolerable.',short='Cemiplimab infusion every 3 weeks; no fixed cycle total in this regimen.',admin='Cemiplimab is infused into a vein over 30 minutes in the source schedule. Allow additional time for assessment, preparation and observation. Tell staff immediately about itching, flushing, chills, pain, dizziness, breathlessness or swelling during the infusion.',missed='If a visit is missed or treatment is held, contact the unit for a new appointment and treatment decision. Do not assume the next scheduled date means treatment has been cleared to restart.',baseline='Full blood count, kidney/liver tests, glucose and thyroid tests; hepatitis B surface antigen, hepatitis B core antibody and hepatitis C testing. Review autoimmune conditions, organ transplantation, previous immune reactions and medicines.',during='Full blood count, kidney/liver tests and glucose each cycle; thyroid-stimulating hormone (TSH) every three to six weeks. Review new symptoms at every visit and arrange additional tests when indicated. Response assessment and scans follow the individual plan.',after='Immune effects can begin or persist after treatment stops. Keep the agreed follow-up, steroid or hormone-replacement instructions and alert card, and tell clinicians about previous cemiplimab. The next scan, skin/lesion review and any further treatment are individually planned.',pregnancy='Use effective contraception during cemiplimab treatment and for at least four months after the last dose. Discuss fertility before treatment, and follow the medicine-specific breastfeeding restrictions. Report a possible pregnancy promptly.',urgent=IMMUNE,agents=[agent('cemiplimab','Cemiplimab','Libtayo','PD-1 checkpoint immunotherapy','Releases a PD-1 immune brake','Cemiplimab blocks PD-1 signalling that can limit T-cell activity. This may help the immune system attack cutaneous squamous cell cancer. Increased immune activity can also inflame healthy organs, so new symptoms need attention even if the visible skin tumour appears to improve.',['PD-1 blocked','Immune response activated','Organ inflammation possible'],'Carry an immunotherapy alert card and report new diarrhoea, cough, breathlessness, rash, weakness or endocrine symptoms promptly.',['Immune inflammation of bowel, lungs, liver or kidneys','Thyroid, pituitary, adrenal and glucose problems','Skin reactions and rare severe skin injury','Rare heart, muscle, neurological and eye inflammation','Infusion reactions','Some immune effects need long-term treatment'],['Bowels','Breathing','Skin','Fatigue'])],anatomy=[],warnings=['This patient suite covers cutaneous SCC only; it does not transfer cervical-cancer treatment context.','The cited NCCP indication is advanced disease unsuitable for curative surgery/radiotherapy; no adjuvant CSCC claim is made.','A visible skin response does not exclude toxicity or establish response elsewhere.'])
for c in ['00431','00812']:
 who='Nivolumab / ipilimumab' if c=='00431' else 'Cemiplimab'
 D[c]['anatomy']=[['brain','Hormones / head / eyes',who,'New severe headache, visual change, unusual tiredness, dizziness, thirst or frequent urination may signal immune effects and needs prompt advice.',50,5],['lungs','Lungs / breathing',who,'New cough or breathlessness may reflect lung inflammation or another serious cause. Call promptly; severe breathing difficulty is an emergency.',58,25],['heart','Heart / muscles',who,'Chest pain, palpitations, marked muscle weakness or swallowing difficulty can be serious immune effects. Seek urgent assessment.',47,24],['liver','Liver',who,'Inflammation may first show in blood tests. Report yellow eyes or skin, dark urine, unusual itching or upper-abdominal pain.',44,34],['kidneys','Kidneys / urine',who,'Kidney inflammation may be detected on blood tests. Report reduced urine, swelling, blood in urine or a marked change from normal.',57,39],['bowel','Bowels / abdomen',who,'Report increased stool frequency, diarrhoea, blood or mucus, or abdominal pain early. Severe pain, black stools or dehydration needs urgent help.',50,44],['skin','Skin / mouth',who,'Report rash or itching early. Blistering, peeling, mouth or genital sores, or rash with fever needs urgent assessment.',22,37],['nerves','Nerves / strength',who,'New tingling, weakness, unsteadiness, facial change or trouble swallowing needs prompt review. Sudden weakness or speech difficulty is an emergency.',63,65]]
# Current retained sources, reconciled with the source-audit handoffs.
D['00415'].update(version='5',url='https://healthservice.hse.ie/documents/6732/415_Trametinib_and_DabrafenibTherapy.pdf',title='Dabrafenib and trametinib for advanced BRAF-mutated melanoma',scope='NCCP 00415a: unresectable or metastatic melanoma with a BRAF V600 mutation. This route covers advanced disease; the separate 00415/adjuvant guide covers the 12-month postoperative setting.',purpose='Dabrafenib and trametinib block two points in a growth pathway used by BRAF V600-mutated melanoma. In this advanced-disease setting the aim is disease control, with the effect on symptoms, side effects and your priorities reviewed regularly.',schedule='Take dabrafenib twice daily, around 12 hours apart, and trametinib once daily. Both are taken every day unless the team instructs a hold. Treatment for advanced melanoma continues while beneficial and tolerable; there is no preset cycle total. A 28-day calendar is a review period, not a treatment-free week.',baseline='Confirm the BRAF V600 tumour result and advanced-disease treatment goal. Full blood count, kidney/liver tests, ECG and echocardiogram, skin examination and eye assessment when indicated.',during='Blood count, kidney/liver tests monthly. ECG and echocardiogram at four weeks, then every 12 weeks and after dose modification. Regular skin reviews are required: ask the team to document the interval because the source gives monthly and 60-day instructions in different sections. Head/neck examination every three months and chest CT every six months are specified surveillance checks; disease-response imaging follows the individual plan.',pregnancy='Discuss fertility and pregnancy precautions before starting. Use an effective alternative to hormonal contraception during treatment and for two weeks after dabrafenib and 16 weeks after trametinib; dabrafenib can make hormonal contraception less effective. The team must confirm the method and the later applicable end date for the combination. Do not breastfeed during treatment; ask when it is safe to resume. Report a possible pregnancy promptly.')
D['00415']['warnings'].append('The current NCCP document gives different skin-review intervals in two sections; the local team must confirm and record the interval rather than treating one as universally agreed.')
D['00563'].update(version='4',url='https://healthservice.hse.ie/documents/6744/563_Encorafenib-and-Binimetinib-Therapy.pdf',admin='The usual method is to swallow the prescribed capsules/tablets whole with water, with or without food. If swallowing is difficult, ask the pharmacist for the source-permitted preparation: Braftovi capsules may be opened into about 20 mL of apple puree for immediate use, and Mektovi 15 mg tablets may be dispersed in about 10 mL of water, orange juice or apple juice, taken immediately, followed by a further 10 mL rinse. Do not assume this applies to other tablet strengths or improvise a preparation. Keep doses at consistent times. Avoid grapefruit and grapefruit juice, and have all medicines and supplements checked.',pregnancy='Use effective contraception during treatment and for at least one month after the last dose. Hormonal contraception needs an additional or alternative barrier method because interactions can reduce effectiveness. Discuss fertility beforehand and follow the team’s breastfeeding instructions. Report a possible pregnancy promptly.')
D['00563']['warnings'].append('Tumour lysis syndrome is a source-listed risk, especially with high tumour burden, kidney problems or dehydration. The team decides whether extra hydration and blood checks are needed.')
D['00563']['urgent']+=' Report markedly reduced urine, persistent vomiting, new muscle cramps or weakness, or palpitations promptly; the team may need to check salts, kidney function and tumour lysis risk.'
# The separate adjuvant route does not inherit the advanced-disease endpoint.
ADJ=copy.deepcopy(D['00415'])
ADJ.update(title='Adjuvant dabrafenib and trametinib after removal of BRAF-mutated stage III melanoma',scope='NCCP 00415b: adjuvant treatment after complete resection of stage III melanoma with a BRAF V600 mutation. This route is distinct from treatment of unresectable or metastatic melanoma.',purpose='After eligible stage III melanoma has been completely removed, dabrafenib and trametinib are offered to reduce the chance of recurrence. The expected benefit, alternatives and treatment burden need an individual discussion; treatment cannot guarantee that melanoma will not return.',schedule='Take dabrafenib twice daily, around 12 hours apart, and trametinib once daily, every day unless the team instructs a hold. The adjuvant course is planned for 12 months, unless stopped earlier for recurrence, side effects or another clinical reason. A four-week review is not a drug holiday or one of 12 chemotherapy cycles.',short='Both medicines daily; adjuvant course planned for 12 months with regular safety reviews.',baseline='Confirm the BRAF V600 result, complete resection of stage III melanoma and the postoperative treatment goal. Full blood count, kidney/liver tests, ECG, echocardiogram, skin examination and eye assessment when indicated.',kind='skin_dabrafenib_trametinib_adjuvant_12_months')

ED={
'melanoma':[
('What the diagnosis says','Keep the pathology summary, original skin site, stage and details of any lymph-node involvement together. Breslow thickness and ulceration describe features of the original melanoma; they are different from the stage. If the diagnosis arose in the eye or a mucosal surface, ask whether this cutaneous-melanoma information applies.'),
('BRAF and other tumour tests','A BRAF V600 result helps decide whether the BRAF/MEK targeted medicines in this guide are suitable. This is usually a test of the tumour, not proof of an inherited family condition. Keep the actual result and test date; ask about genetic counselling only when your personal or family history makes that relevant.'),
('Surgery, radiotherapy and medicine have different roles','Record what surgery removed and whether the present medicine is postoperative treatment to lower recurrence risk or treatment of cancer that remains or has spread. Radiotherapy, stereotactic treatment or another operation may have a separate role; their timing and side effects need their own plan.'),
('Stage and response are different','Stage describes the extent of melanoma at diagnosis or a later reassessment. A response assessment asks how known cancer has changed with treatment. In the adjuvant setting there may be no visible tumour to measure: surveillance looks for recurrence while safety checks look for medicine effects.'),
('A new skin change still needs review','Continue to report a new or changing mole, a non-healing lesion, a new lump or an unexplained persistent symptom. Do not assume every new lesion is melanoma, and do not use a photograph or a good response at one site to rule out a problem elsewhere.')],
'cscc':[
('Confirm that this is skin SCC','This guide concerns cutaneous squamous cell carcinoma arising in the skin. Squamous cancers beginning inside the mouth, throat, lung or cervix have different treatment pathways. Record the original skin site, pathology date and whether the cancer has returned or spread.'),
('Why a cancer is considered high risk','The size, depth, site, growth pattern and involvement of nerves, lymph nodes or other structures can affect the plan. Prior treatment, recurrence and reduced immunity also matter. Ask the team to explain the risk features in your report in ordinary language; a risk category is not itself a treatment response.'),
('Why medicine is being offered','The cited NCCP cemiplimab setting is advanced skin SCC when curative surgery or radiotherapy is not appropriate. Record the multidisciplinary team’s reason and the aim of treatment. This guide does not make a general promise that immunotherapy will avoid surgery or cure the cancer.'),
('Immunity and transplantation','Tell the oncology team about an organ transplant, immune-suppressing medicines, autoimmune illness and previous immune treatment. These can substantially change the balance of benefit and harm. Never stop transplant or steroid medicines yourself; the relevant specialists need a shared plan.'),
('Lesions, wounds and daily function','A skin tumour or treatment can affect pain, bleeding, wound care, movement, eating, appearance or sleep. Ask for a wound and symptom plan that names who to contact. Worsening bleeding, infection symptoms, new nerve pain or weakness should be assessed rather than waiting for a photograph comparison.')],
'bcc':[
('Confirm the diagnosis and extent','Keep the biopsy result, original site, dates and details of previous treatment. Basal cell carcinoma usually remains local, but some tumours become difficult to remove or rarely spread. Your team should explain whether the present problem is locally advanced disease or metastatic disease.'),
('Why tablets are being considered','The cited NCCP vismodegib pathway concerns symptomatic metastatic BCC, or locally advanced BCC unsuitable for surgery or radiotherapy. Ask what makes those local treatments unsuitable in your case and what benefit is realistic. A systemic capsule is different from a cream for a small superficial lesion.'),
('Record earlier local treatment','Record operations, margin results, reconstruction, radiotherapy and any previous BCC medicines. The effect on sight, movement, pain, wound healing and appearance may influence choices. More than one specialist may be needed to agree the sequence and practical support.'),
('Inherited conditions and multiple cancers','Tell the team if you have had many BCCs at a young age or an established inherited condition such as Gorlin syndrome. This does not mean everyone with BCC needs genetic testing. Ask whether a specialist skin-surveillance or genetic advice plan is appropriate for your own history.'),
('A visible lesion is only one part of assessment','Changes in a lesion, pain or a wound may be useful to track, but they do not replace examination and any agreed imaging. Report new skin lesions separately. If you use photographs, agree how and when the clinical team will compare them and how you will keep them private.')]
}
FOLLOW={
'melanoma':'Follow-up depends on stage, treatment and symptoms. Your team records the skin/lymph-node examination plan, whether body or brain imaging is needed, and which service owns each appointment. A general patient booklet does not set a universal scan interval for every patient.',
'cscc':'Follow-up includes examination of the treated area, the rest of the skin and relevant lymph nodes. Imaging and specialist visits depend on the extent of disease, risk features, symptoms and treatment response. Keep a clear wound and skin-surveillance plan alongside oncology visits.',
'bcc':'Keep follow-up for the treated lesion and for other skin cancers. Examination and any imaging are tailored to the disease and treatment; locally advanced disease needs an individual plan. Continuing precautions after vismodegib are part of follow-up even when the cancer medicine has stopped.'}

def education_chapters(c,d,adjuvant=False):
 ids=['nccp'];nids=['nccn-patient']
 return [
 chapter('understand-diagnosis','Understanding your diagnosis and treatment goal','Use these questions with your own pathology report and agreed treatment plan.',[item(t,x,nids) for t,x in ED[d['context']]]),
 chapter('your-treatment','Your medicines and the overall plan',d['purpose'],[item('The schedule in this setting',d['schedule'],ids),item('How the treatment works',' '.join(a['explanation'] for a in d['agents']),ids),item('The role of earlier or later treatment','Record surgery, radiotherapy and other anticancer medicines separately, including dates and the specialist responsible. This schedule does not automatically include or authorise another treatment. Ask whether any overlap changes tests, symptoms to report or the timing of appointments.',nids),item('Pauses and stopping','A safety pause is an active treatment decision. Record which medicine is paused, the reason, the tests or recovery needed and who may authorise restarting. Do not restart from an old prescription or reset the history when a new phase begins.',ids)]),
 chapter('how-to-receive','Taking treatment and preparing for visits','Keep the written medicine plan beside this guide; it records your own dose and dates.',[item('Taking or receiving the medicine',d['admin'],ids),item('Missed, vomited or held treatment',d['missed'],ids),item('Other medicines and supplements','Show the pharmacist a current list of prescriptions, over-the-counter medicines, vitamins, herbal products and supplements. Include anticoagulants, heart medicines, steroids and recent antibiotics. Check before adding, stopping or changing anything; an apparently harmless product can alter treatment or confuse a symptom assessment.',ids),item('Practical preparation','Arrange medicine supply, transport, interpreter or carer support before it is needed. Bring the alert card, symptom record and questions. Ask which appointments require someone to accompany you and how to obtain urgent advice outside normal hours.',nids)]),
 chapter('tests-and-results','Tests: what is required and what each result means','Safety tests, tumour tests and response scans answer different questions.',[item('Before treatment',d['baseline'],ids),item('During treatment',d['during'],ids),item('Scans and tumour markers','Ask the team to write the next assessment and who will arrange it. Bloods used to monitor kidneys, liver, hormones or muscle are not automatically measures of cancer response. There is no universal tumour-marker blood schedule for these skin-cancer regimens; a scan or extra blood test is requested for a specific clinical reason.',ids),item('After a pause or finish',d['after'],ids),item('Getting the result','For each test, record its purpose, due date, result and action. Agree how results reach you and who checks a result from another hospital. If an appointment or result has not arrived, contact the named service rather than assuming no news means no action is needed.',nids)]),
 chapter('between-visits','What to expect between visits','You can feel well and still need the planned checks. New symptoms deserve attention even on a day without an appointment.',[item('Your usual pattern','Record the start and change in symptoms, temperature if advised, bowel pattern, drinking, urine and the effect on normal tasks. A simple few-line record is enough. Use it to describe a change rather than trying to grade or diagnose a toxicity yourself.',ids),item('When to call',d['urgent'],ids),item('Eating, drinking and activity','Tell the team early about nausea, taste change, a sore mouth, diarrhoea or falling weight. Ask for an individual fluid and food plan if heart, kidney or other conditions limit intake. Gentle activity and planned rest can help maintain function; adjust to symptoms and ask for support when fatigue limits daily life.',nids),item('A held dose and a new phase',d['missed'],ids)]),
 chapter('skin-self-care','Skin checks, sun protection and optional photographs','This complements clinical assessment and does not replace it.',[item('Protect your skin','Use shade, protective clothing, a hat and broad-spectrum sunscreen of at least SPF 30, and avoid tanning beds. Reapply sunscreen according to its instructions. Protection matters even when it is cloudy; choose a practical approach that lets you remain active safely.',nids),item('Know the pattern of your skin','Ask how to examine your skin, scars and relevant lymph-node areas and how often your own team recommends doing so. A mirror or a trusted helper can make hard-to-see areas easier to check. Report a new or changing lesion, a non-healing sore or a new lump rather than waiting for a routine visit.',nids),item('Photographs are optional','If useful, keep a dated photograph with consistent lighting and a size reference, following your team’s advice. Photographs are optional and do not diagnose a cancer or replace examination. Keep them privately; this printable passport does not require you to upload images or other personal health information.',nids),item('Wounds, nails and sensitive skin','Use the dressings and skin-care plan recommended for your lesion and treatment. Ask before applying new creams or remedies to an open or treated area. Worsening pain, discharge, redness, bleeding or loss of function needs advice; routine skin-care instructions are not a substitute for assessment.',nids)]),
 chapter('fertility-pregnancy','Pregnancy, fertility and protecting others','Discuss these precautions before treatment even if pregnancy is not currently planned.',[item('Medicine-specific precautions',d['pregnancy'],ids),item('Planning ahead','Ask early about fertility preservation, sexual health and symptoms affecting intimacy. Tell the team about any chance of pregnancy, breastfeeding or a partner’s pregnancy so that the correct medicine-specific advice can be given. Keep the precautions and their end dates in the written plan.',ids),item('Safe handling and supply','Do not share anticancer medicines. Keep oral medicines in their original labelled packaging, away from children and anyone who could take them accidentally. Return unused medicines to the supplying pharmacy and follow its handling advice. A treatment hold does not remove pregnancy precautions.',ids)]),
 chapter('choices-and-support','Questions, decisions and practical support','Your priorities and the burden of treatment belong in the discussion.',[item('Benefits and uncertainties','Ask what evidence applies to your diagnosis, stage, biomarker and treatment setting, what outcome the team hopes to improve, and what may happen without this treatment. A trial average cannot predict an individual result; a benefit measured in one setting should not be transferred to another.',nids),item('Alternatives and review points','Discuss other suitable treatments, clinical trials if relevant, local treatment options and symptom-focused care. Ask when the decision will be reviewed and what would prompt a change. Supportive and palliative care can help with symptoms and quality of life alongside anticancer treatment.',nids),item('Help with daily life','Tell the team about work, transport, caring responsibilities, cost concerns, body image, anxiety or sleep. Ask which nurse, social worker, dietitian, rehabilitation professional or support organisation can help. Use resources relevant to your country and service; a US guide may describe different access or funding.',nids),item('Shared understanding','Ask someone on the team to check that you can explain the medicine schedule, next tests and urgent-contact route in your own words. An interpreter, large-print copy or a trusted supporter can help; none requires you to use a smartphone.',nids)]),
 chapter('after-treatment','Follow-up and your continuing record','Keep this record when treatment is paused, changed or completed.',[item('Your follow-up plan',FOLLOW[d['context']],nids),item('Continuing medicine precautions',d['after'],ids),item('Treatment summary for other clinicians','Record the medicines and last dates, important reactions, any long-term hormone replacement or steroid taper, and the responsible oncology contact. Show this information in urgent care and to other specialists. A different treatment phase does not erase earlier toxicity.',ids),item('The complete paper version','This handbook can be used without a phone: keep the schedule, symptom advice, medicine list, tests and contacts together. The QR code is an optional route to the matching regimen information. Ask the team to print updates when your plan changes and keep the latest dated copy.',nids)])]

def phases_for(c,d,adjuvant=False):
 if c=='00431':return [dict(id='induction',label='Combination induction',short='Up to four visits',cycles=['Nivolumab then ipilimumab','Every 21 days, up to four doses'],agents=['nivolumab','ipilimumab'],detail='Nivolumab 1 mg/kg and ipilimumab 3 mg/kg are given by IV infusion, subject to review before every dose. Four is the planned combination limit, not the total number of all treatment visits.'),dict(id='maintenance',label='Nivolumab alone',short='Maintenance',cycles=['Every 2 or 4 weeks as prescribed','IV or subcutaneous route as selected'],agents=['nivolumab'],detail='After the last melanoma combination dose, the first two-weekly nivolumab dose starts three weeks later or the first four-weekly dose six weeks later. The team confirms dose, route, interval and start date. Treatment continues while beneficial and tolerable; previous immune-toxicity decisions still apply.')]
 return [dict(id='treatment',label='Adjuvant oral treatment' if adjuvant else 'Continuous oral treatment' if d['service']=='targeted' else 'Cemiplimab treatment',short='12-month planned course' if adjuvant else 'Daily medicines' if d['service']=='targeted' else 'Every three weeks',cycles=['Planned 12 months; regular reviews'] if adjuvant else ['No preset cycle total',d['short']],agents=[a['id'] for a in d['agents']],detail=d['schedule'])]

