 ids=['nccp'];allids=['nccp','nccn-patient'];oral=d['service']=='targeted';n=NCCN[d['context']];phases=phases_for(c,d,adjuvant)
 p=dict(schema_version=1,content_version=V,suite_release=V,patient_layout_release=V,review_status=REVIEW,source_checked=DATE,document_revision=DATE,protocol_id=f'nccp-{c}-v{d["version"]}',code=c,protocol_version=d['version'],title=d['title'],cycle_days=d['cycle'],context_label=d['scope'],purpose=d['purpose'],schedule_summary=d['schedule'],scope_heading='Your diagnosis and treatment setting',scope_note=d['scope'],service_kind=d['service'],therapy_label=d['therapy'],schedule_kind=d['kind'],schedule_label='Reference calendar for daily medicine and reviews' if oral else 'Reference treatment cycle',indication_text=d['scope'],phases_title='The overall treatment plan',phases_note='The treatment setting determines duration; a reference calendar is not a prescription or a reason to restart a held medicine.',medicines_title='Medicines in this regimen',timeline_note='This calendar shows the pattern. Your team supplies actual dates, prescribed doses and any hold or restart instructions.',safety_note='The prescribed dose, treatment decision and local urgent-contact plan take priority. '+EMERGENCY,teachback='Can you explain your treatment setting, medicine schedule, next tests, the symptoms that need urgent advice and the number you would call?',consent_support='Discuss the exact diagnosis, treatment intent, expected benefits and uncertainty, suitable alternatives, the regimen-specific risks and monitoring, fertility and pregnancy precautions, and practical burdens. Confirm the treatment phase and route. This guide supports the conversation and does not replace individual consent.',urgent_extra=d['urgent'],timeline_source_ids=ids,support_source_ids=allids,urgent_source_ids=ids,sources=[dict(id='nccp',title=f'NCCP {c} v{d["version"]}: current regimen source',url=d['url'],checked=DATE),dict(id='nccn-patient',title=n['title'],url=n['url'],page_anchors=n['pages'],role='Education reference; source-specific Irish regimen decisions remain governed by NCCP')],agents=d['agents'],cycle_display='reference-chronology',port_pump=False,longitudinal_mapping=True,passport_visit_note='Record the actual date, treatment received, any hold, important symptom and the next check. A review visit is not automatically a medicine dose or a completed cycle.',anatomy_note='The established anatomical illustration links body areas to the full regimen-specific descriptions. A body location helps explain possible effects; it does not diagnose the cause of a symptom or indicate its frequency.',anatomy=d['anatomy'],phases=phases,chronology_notes=[d['schedule'],d['missed']]+d['warnings'],administration_text=d['admin'],monitoring_summary=d['baseline']+' '+d['during']+' '+d['after'],passport_context=d['context'],passport_groups=[dict(title=('Adjuvant course: monthly review record, planned 12 months' if adjuvant else 'Daily medicines and review record' if oral else 'Combination induction: doses 1–4' if c=='00431' else 'Cemiplimab: ongoing treatment visits'),agents=[a['id'] for a in d['agents']])])
 if adjuvant:p.update(patient_context='adjuvant',route_context='adjuvant')
 if c=='00431':p['passport_groups'].append(dict(title='Nivolumab maintenance: interval and route as prescribed',agents=['nivolumab']))
 if oral:
  p['timeline']=[dict(id='daily',label='Daily oral treatment',start=1,end=d['cycle'],style='treatment',text=d['short']),dict(id='checks',label='Safety reviews as scheduled',start=1,end=d['cycle'],style='monitor',text='Keep the specific blood, organ and skin-review appointments; they do not all follow the same interval.'),dict(id='watch',label='Symptoms and support',start=1,end=d['cycle'],style='watch',text=d['urgent'])]
  p['day_groups']=[dict(start=1,end=d['cycle'],title='Every day in the reference calendar',body=d['short'],action='Use the written medicine plan; report new symptoms and keep tests even during a treatment hold.')]
 else:
  p['timeline']=[dict(id='dose',label='Combination infusion' if c=='00431' else 'Cemiplimab infusion',start=1,end=1,style='treatment',text='Treatment after clinical review and the required tests.'),dict(id='watch',label='Symptoms between visits',start=1,end=21,style='watch',text='Immune effects can begin at any time, including after treatment stops.'),dict(id='checks',label='Next-cycle assessment',start=21,end=21,style='monitor',text='The team confirms the next dose; maintenance has its own schedule.' if c=='00431' else 'The team confirms whether the next dose can proceed.')]
  p['day_groups']=[dict(start=1,end=1,title='Treatment visit',body=d['admin'],action='Report symptoms and previous reactions before treatment.'),dict(start=2,end=21,title='Between visits',body=IMMUNE,action='Do not wait for the next infusion to report a possible immune effect.')]
 p['support']=[item('An individual symptom plan','Ask which anti-sickness or other symptom medicines are prescribed, when to take them and when to call if they do not help. Do not start a borrowed medicine or alter treatment to manage a side effect yourself.',ids),item('Your urgent contacts',CONTACT,ids),item('Pregnancy and fertility precautions',d['pregnancy'],ids),item('Eating, activity and practical help','Report falling intake, weight loss, pain or fatigue early. The team can tailor nutrition, activity, wound, psychological and practical support to your needs.',allids)]
 if c=='00415':p['support'].insert(0,item('Fever action plan','If temperature reaches 38°C or higher, withhold both dabrafenib and trametinib and contact your oncology team promptly for assessment. For recurrent episodes, the team may advise withholding at the first symptom. Restarting needs the team’s plan after at least 24 hours without symptoms; do not use this as an automatic self-restart rule.',ids))
 if c=='00563':p['support'].append(item('Hydration and tumour lysis assessment','The team checks whether tumour burden, kidney problems or dehydration call for additional precautions and blood tests. Keep the individual fluid plan; do not force fluids if you have a restriction. Report reduced urine, persistent vomiting or marked weakness promptly.',ids))
 if c=='00236':p['support'].insert(0,item('Formal pregnancy-prevention programme','The programme materials, supervised tests, contraceptive methods and after-treatment restrictions must be agreed and documented before the first dose; they apply even during a treatment pause.',ids))
 if not oral:p['support'].append(item('Steroids and hormone replacement','Some immune effects need steroids or lasting hormone replacement. Follow the exact prescription and taper. Carry the relevant alert information, and do not stop or reduce these medicines yourself when anticancer treatment is held or completed.',ids))
 p['monitoring_schedule']=dict(title='Required safety checks and your individual disease-assessment plan',columns=['Before starting','During treatment','Between visits','Response / follow-up','After a hold or stop'],rows=[dict(label='Bloods and organ safety',cells=[d['baseline'],d['during'],'Contact the team for new symptoms; extra tests may be needed between scheduled checks.','Safety bloods do not by themselves show whether cancer is responding.',d['after']]),dict(label='Cancer, skin and daily function',cells=['Record diagnosis, stage, current disease sites and the baseline assessment.','Keep the source-specific skin and clinical reviews and the individually agreed response assessments.','Record new lesions, lumps, wound changes, pain and effects on usual activities.','Write the next examination or scan date and the responsible team; no universal scan or tumour-marker interval is assumed.',FOLLOW[d['context']]]),dict(label='Medicines and continuing precautions',cells=['Review all medicines and the pregnancy/fertility plan.','Review treatment taken or received, holds, adverse effects and supportive medicines.','Keep the actual urgent contacts and do not restart a held medicine yourself.','Bring the medicine list and treatment summary to other services.',d['pregnancy']])],note='The team supplies actual dates and resolves any source ambiguity. A reference period does not replace a prescription, a local monitoring plan or an individual treatment decision.',source_ids=allids)
 p['logistics']=dict(sections=[item('Taking or receiving treatment',d['admin'],ids),item('Missed, vomited or held treatment',d['missed'],ids),item('Appointments and supply','Arrange dates, medicine supply, transport and any needed interpreter or carer support. Ask whether bloods are taken in the oncology unit or elsewhere and how the result reaches the prescriber.',allids),item('Paper copies and contact information','Keep this complete handbook, the three-page summary and the wallet card together. The QR code is optional. Ask the team to add your actual contacts and print a revised plan when treatment changes.',allids)])
 p['evidence']=dict(title='What the evidence means for your treatment',intro='The evidence discussion must match the diagnosis, biomarker and treatment setting shown in this guide.',population=d['scope'],metrics=[],interpretation='Ask which outcomes matter in your setting and what benefit is realistic for you. No survival percentage from another regimen, dose combination or disease setting is assigned here.',limitations=['Individual benefit and risk cannot be predicted from a group average.','The supplied NCCN patient guide is an education reference, not Irish prescribing or reimbursement authority.','This handoff does not claim a completed independent quantitative trial-benefit audit.'],source_ids=allids)
 p['chapters']=education_chapters(c,d,adjuvant)
 p['questions']=[dict(q='What is the aim of my treatment?',a=d['purpose']),dict(q='Is there a fixed number of cycles?',a=d['schedule']),dict(q='What happens if treatment is held?',a=d['missed']),dict(q='When are my next tests?',a=d['during']+' Your team adds the actual dates.'),dict(q='Can I use this without a smartphone?',a='Yes. The full handbook, three-page summary and wallet card are printable. The QR code is optional; keep actual contacts and written appointments on the paper copy.')]
 p['patient_summary']=dict(template_version=V,purpose=('After complete removal of eligible BRAF V600 stage III melanoma; aims to lower recurrence risk.' if adjuvant else d['purpose']),schedule=d['short'],phases=[dict(title=x['label'],text=x['detail'] if c=='00431' else ('Planned 12 months; no routine drug holiday.' if adjuvant else 'Continue while beneficial and tolerable, with team review; no fixed cycle total.')) for x in phases],monitoring=[dict(stage='Before',test='Baseline safety',when=d['baseline'],basis='NCCP / medicine-specific precautions'),dict(stage='During',test='Bloods and organ checks',when=d['during'],basis='NCCP; local interval clarification where stated'),dict(stage='After / response',test='Follow-up',when=d['after'],basis='Regimen / individual disease plan')],cycle_expectations=[('Both oral medicines continue daily unless the team tells you to pause.' if len(d['agents'])==2 and oral else 'Daily treatment continues unless the team tells you to pause.' if oral else 'Immune symptoms can occur between visits or after the last dose.'),('A review date does not automatically clear a held medicine to restart.' if oral else 'Tell every clinician about immunotherapy and carry the alert card.')],preparation=['Bring the written medicine plan, test dates and actual oncology/out-of-hours contacts.'],card_title='My Treatment Card',card_schedule=d['short'],card_cycle_count=4 if c=='00431' else None,card_record_note=('Stamp or record combination doses 1–4 only; keep a separate ongoing nivolumab maintenance record. This is not a four-dose total treatment course.' if c=='00431' else 'Use a dated month/review record for the planned 12-month adjuvant course; 12 months does not mean 12 doses or 12 cycles.' if adjuvant else 'Use a dated medicine/review record, including holds. Continuous treatment has no fixed completion stamp total.' if oral else 'Use an ongoing dated visit record; there is no preset completion stamp total.'),card_alert=d['urgent'],summary_checked=DATE)
 p['treatment_scope_notice']=d['scope']+' This information supports individual consent; it does not issue or change a prescription.'
 return p

